import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Subject, takeUntil } from 'rxjs';
import { LateInDataService } from './core/services/late-in-data.service';
import { PersonaService } from './core/services/persona.service';
import { ValidationService } from './core/services/validation.service';
import { ToastService } from './core/services/toast.service';
import { LateInRecord, PaginationConfig, SortConfig, ValidationError } from './core/models/late-in-record.model';
import { Persona, PersonaType, PERSONAS } from './core/models/persona.model';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.complete.html',
  styleUrls: ['./app.component.complete.scss']
})
export class AppComponent implements OnInit, OnDestroy {
  private destroy$ = new Subject<void>();

  // State
  showLogin = true;
  showLoading = false;
  records: LateInRecord[] = [];
  selectedRows = new Set<number>();
  currentPersona!: Persona;
  pagination!: PaginationConfig;
  sortConfig!: SortConfig;

  // Validation
  validationErrors: string[] = [];
  showValidationBanner = false;
  errorFields = new Set<string>();

  // Filters
  filters = {
    station: 'DTW - Detroit',
    customer: 'All Customers',
    lineOfService: 'All Services',
    jobCode: 'All Job Codes',
    excusedStatus: '',
    dateRange: 'yesterday'
  };
  showDatePicker = false;

  // Stats
  stats = {
    pending: 0,
    excused: 0,
    unexcused: 0
  };

  // Bulk Actions
  showBulkExcusedModal = false;
  showBulkCommentModal = false;
  bulkExcusedValue = '';
  bulkCommentValue = '';

  // Toast
  toastMessage = '';
  toastType: 'success' | 'error' | 'info' = 'info';
  showToast = false;

  // Dropdowns
  personas = Object.values(PERSONAS);
  stations = ['DTW - Detroit', 'ORD - Chicago', 'LAX - Los Angeles'];
  customers = ['All Customers', 'Delta Airlines', 'United Airlines'];
  lineOfServices = ['All Services', 'Cargo', 'Passenger'];
  jobCodes = ['All Job Codes', 'Ramp Agent', 'Supervisor'];

  constructor(
    private dataService: LateInDataService,
    private personaService: PersonaService,
    private validationService: ValidationService,
    private toastService: ToastService
  ) {}

  ngOnInit(): void {
    this.subscribeToData();
    this.subscribeToToast();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private subscribeToData(): void {
    this.dataService.getPagedRecords()
      .pipe(takeUntil(this.destroy$))
      .subscribe(records => {
        this.records = records;
        this.updateStats();
      });

    this.dataService.selectedRows$
      .pipe(takeUntil(this.destroy$))
      .subscribe(selected => {
        this.selectedRows = selected;
      });

    this.personaService.currentPersona$
      .pipe(takeUntil(this.destroy$))
      .subscribe(persona => {
        this.currentPersona = persona;
      });

    this.dataService.pagination$
      .pipe(takeUntil(this.destroy$))
      .subscribe(pagination => {
        this.pagination = pagination;
      });

    this.dataService.sortConfig$
      .pipe(takeUntil(this.destroy$))
      .subscribe(sortConfig => {
        this.sortConfig = sortConfig;
      });
  }

  private subscribeToToast(): void {
    this.toastService.toast$
      .pipe(takeUntil(this.destroy$))
      .subscribe(toast => {
        this.toastMessage = toast.message;
        this.toastType = toast.type;
        this.showToast = toast.show;
      });
  }

  // Login/Logout
  login(): void {
    this.showLoading = true;
    setTimeout(() => {
      this.showLogin = false;
      this.showLoading = false;
      this.toastService.showSuccess('Login successful!');
    }, 1500);
  }

  logout(): void {
    if (confirm('Are you sure you want to logout?')) {
      this.showLoading = true;
      setTimeout(() => {
        this.showLogin = true;
        this.showLoading = false;
        this.dataService.clearSelection();
        this.toastService.showInfo('Logged out successfully');
      }, 1000);
    }
  }

  // Persona
  changePersona(personaType: PersonaType): void {
    this.personaService.switchPersona(personaType);
    this.dataService.clearSelection();
    this.toastService.showInfo(`Switched to ${PERSONAS[personaType].role} view`);
  }

  // Filters
  applyFilters(): void {
    this.showLoading = true;
    setTimeout(() => {
      this.dataService.applyFilters({
        excusedStatus: this.filters.excusedStatus
      });
      this.showLoading = false;
      this.toastService.showSuccess('Filters applied successfully');
    }, 1000);
  }

  resetFilters(): void {
    this.filters = {
      station: 'DTW - Detroit',
      customer: 'All Customers',
      lineOfService: 'All Services',
      jobCode: 'All Job Codes',
      excusedStatus: '',
      dateRange: 'yesterday'
    };
    this.dataService.applyFilters({});
    this.toastService.showInfo('Filters reset to default');
  }

  refreshGrid(): void {
    this.showLoading = true;
    setTimeout(() => {
      this.applyFilters();
      this.showLoading = false;
      this.toastService.showSuccess('Grid refreshed successfully');
    }, 1000);
  }

  toggleDatePicker(): void {
    this.showDatePicker = !this.showDatePicker;
  }

  selectDateOption(option: string): void {
    this.filters.dateRange = option;
    this.showDatePicker = false;
    this.toastService.showInfo('Date filter updated');
  }

  getDateLabel(): string {
    const labels: Record<string, string> = {
      'yesterday': 'Yesterday',
      '2days': '2 Days Ago',
      '3days': '3 Days Ago'
    };
    return labels[this.filters.dateRange] || 'Yesterday';
  }

  // Stats
  private updateStats(): void {
    this.dataService.filteredRecords$
      .pipe(takeUntil(this.destroy$))
      .subscribe(allRecords => {
        this.stats.pending = allRecords.filter(r => !r.excused).length;
        this.stats.excused = allRecords.filter(r => r.excused === 'Yes').length;
        this.stats.unexcused = allRecords.filter(r => r.excused === 'No').length;
      });
  }

  // Grid Actions
  toggleRowSelection(id: number): void {
    this.dataService.toggleRowSelection(id);
  }

  selectAll(): void {
    this.dataService.selectAll();
  }

  toggleSelectAll(): void {
    if (this.selectedRows.size === this.records.length && this.records.length > 0) {
      this.dataService.clearSelection();
    } else {
      this.selectAll();
    }
  }

  updateField(id: number, field: keyof LateInRecord, value: any): void {
    this.dataService.updateRecord(id, field, value);
    this.errorFields.delete(`${id}-${field}`);
  }

  sortTable(column: string): void {
    this.dataService.applySort(column);
    this.toastService.showInfo(`Sorted by ${column}`);
  }

  getSortIcon(column: string): string {
    if (this.sortConfig.column !== column) return '⇅';
    return this.sortConfig.direction === 'asc' ? '↑' : '↓';
  }

  // Pagination
  goToPage(page: number): void {
    this.dataService.changePage(page);
  }

  changeRowsPerPage(event: Event): void {
    const select = event.target as HTMLSelectElement;
    this.dataService.changeRowsPerPage(parseInt(select.value));
    this.toastService.showInfo(`Showing ${select.value} rows per page`);
  }

  getPageNumbers(): number[] {
    const pages: number[] = [];
    const maxVisible = 7;
    let startPage = Math.max(1, this.pagination.currentPage - 3);
    let endPage = Math.min(this.pagination.totalPages, startPage + maxVisible - 1);

    if (endPage - startPage < maxVisible - 1) {
      startPage = Math.max(1, endPage - maxVisible + 1);
    }

    for (let i = startPage; i <= endPage; i++) {
      pages.push(i);
    }

    return pages;
  }

  // Bulk Actions
  openBulkExcusedModal(): void {
    this.bulkExcusedValue = '';
    this.showBulkExcusedModal = true;
  }

  closeBulkExcusedModal(): void {
    this.showBulkExcusedModal = false;
  }

  applyBulkExcused(): void {
    if (!this.bulkExcusedValue) {
      this.toastService.showError('Please select an Excused status');
      return;
    }

    const ids = Array.from(this.selectedRows);
    this.dataService.bulkUpdateExcused(ids, this.bulkExcusedValue as 'Yes' | 'No');
    this.closeBulkExcusedModal();
    this.toastService.showSuccess(`Excused status updated for ${ids.length} record(s)`);
  }

  openBulkCommentModal(): void {
    this.bulkCommentValue = '';
    this.showBulkCommentModal = true;
  }

  closeBulkCommentModal(): void {
    this.showBulkCommentModal = false;
  }

  applyBulkComment(): void {
    if (!this.bulkCommentValue || !this.bulkCommentValue.trim()) {
      this.toastService.showError('Please enter a comment');
      return;
    }

    if (this.bulkCommentValue.length > 500) {
      this.toastService.showError('Comment exceeds 500 character limit');
      return;
    }

    const ids = Array.from(this.selectedRows);
    this.dataService.bulkUpdateComment(ids, this.bulkCommentValue);
    this.closeBulkCommentModal();
    this.toastService.showSuccess(`Comment applied to ${ids.length} record(s)`);
  }

  getBulkCharCount(): string {
    const length = this.bulkCommentValue ? this.bulkCommentValue.length : 0;
    return `${length} / 500`;
  }

  getBulkCharCountClass(): string {
    const length = this.bulkCommentValue ? this.bulkCommentValue.length : 0;
    if (length > 450) return 'error';
    if (length > 400) return 'warning';
    return '';
  }

  // Validation
  approveSelected(): void {
    const selectedRecords = Array.from(this.selectedRows)
      .map(id => this.records.find(r => r.id === id))
      .filter(r => r !== undefined) as LateInRecord[];

    const errors = this.validationService.validateRecords(selectedRecords, this.currentPersona);

    if (errors.length > 0) {
      this.validationErrors = errors.map(e => `${e.employeeId}: ${e.message}`);
      this.showValidationBanner = true;
      errors.forEach(e => this.errorFields.add(`${e.employeeId}-${e.field}`));
      this.toastService.showError('Please fix validation errors');
      return;
    }

    this.showValidationBanner = false;
    this.errorFields.clear();

    const count = selectedRecords.length;
    if (!confirm(`Approve ${count} selected record(s)?`)) {
      return;
    }

    this.showLoading = true;
    setTimeout(() => {
      this.dataService.clearSelection();
      this.showLoading = false;
      this.toastService.showSuccess(`${count} record(s) approved and sent to Kronos`);
    }, 2000);
  }

  hasError(id: number, field: string): boolean {
    return this.errorFields.has(`${id}-${field}`);
  }

  // Helpers
  getExcusedClass(excused: string): string {
    if (excused === 'Yes') return 'excused-yes';
    if (excused === 'No') return 'excused-no';
    return 'excused-empty';
  }

  getCharCount(comment: string): string {
    const length = comment ? comment.length : 0;
    return `${length} / 500`;
  }

  getCharCountClass(comment: string): string {
    const length = comment ? comment.length : 0;
    if (length > 450) return 'error';
    if (length > 400) return 'warning';
    return '';
  }

  getKronosIcon(status: string): string {
    if (status === 'success') return '🟢';
    if (status === 'pending') return '🟡';
    return '🔴';
  }

  getKronosText(status: string): string {
    if (status === 'success') return 'Success';
    if (status === 'pending') return 'Pending';
    return 'Failed';
  }

  // File Upload (for AMH)
  handleFileUpload(event: Event, rowId: number): void {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];

    if (!file) return;

    if (file.size > 10 * 1024 * 1024) {
      this.toastService.showError('File too large. Maximum size is 10MB');
      input.value = '';
      return;
    }

    this.dataService.updateRecord(rowId, 'amhAttachment', file.name);
    this.toastService.showSuccess('File uploaded successfully');
  }

  removeFile(rowId: number): void {
    this.dataService.updateRecord(rowId, 'amhAttachment', null);
    this.toastService.showInfo('File removed');
  }
}
<!-- Login Screen -->
<div class="login-screen" *ngIf="showLogin">
  <div class="login-card">
    <div class="login-logo">
      <div class="logo-circle">iL</div>
      <h1>iLink Attendance System</h1>
      <p>Late In Exception Management</p>
    </div>

    <button class="azure-btn" (click)="login()">
      <span>🔐</span>
      <span>Sign in with Azure AD</span>
    </button>

    <div class="demo-notice">
      <strong>📺 Demo Mode</strong>
      <p>After login, you can switch between different user roles (SM, AMH, Operations, Admin) using the role selector.</p>
    </div>
  </div>
</div>

<!-- Main Application -->
<div class="app-container" *ngIf="!showLogin">
  <!-- Header -->
  <div class="app-header">
    <div class="header-content">
      <div class="header-left">
        <div class="app-logo">iL</div>
        <div class="header-title">
          <h1>iLink Attendance System</h1>
          <p>Late In Exception Management</p>
        </div>
      </div>
      <div class="header-right">
        <div class="user-badge">
          <div class="user-avatar">{{ currentPersona.avatar }}</div>
          <div class="user-info">
            <div class="user-name">{{ currentPersona.name }}</div>
            <div class="user-role">{{ currentPersona.role }}</div>
          </div>
        </div>
        <button class="logout-btn" (click)="logout()">Logout</button>
      </div>
    </div>
  </div>

  <!-- Main Content -->
  <div class="main-content">
    <!-- Page Header -->
    <div class="page-header">
      <div class="page-header-top">
        <div class="page-title">
          <div class="page-icon">⏰</div>
          <div class="page-title-text">
            <h2>Late In Management</h2>
            <p>Review and process employee late arrival exceptions</p>
          </div>
        </div>
        <div class="demo-selector">
          <label>🎭 Demo Role:</label>
          <select [(ngModel)]="currentPersona.id" (change)="changePersona($any($event.target).value)">
            <option *ngFor="let persona of personas" [value]="persona.id">
              {{ persona.role }}
            </option>
          </select>
        </div>
      </div>
    </div>

    <!-- Filters Section -->
    <div class="filters-section">
      <div class="filters-title">
        <span>🔍</span>
        <span>Filters</span>
      </div>
      <div class="filters-grid">
        <div class="filter-group">
          <label class="filter-label">Station</label>
          <select class="filter-select" [(ngModel)]="filters.station">
            <option *ngFor="let station of stations" [value]="station">{{ station }}</option>
          </select>
        </div>
        <div class="filter-group">
          <label class="filter-label">Customer</label>
          <select class="filter-select" [(ngModel)]="filters.customer">
            <option *ngFor="let customer of customers" [value]="customer">{{ customer }}</option>
          </select>
        </div>
        <div class="filter-group">
          <label class="filter-label">Line of Service</label>
          <select class="filter-select" [(ngModel)]="filters.lineOfService">
            <option *ngFor="let los of lineOfServices" [value]="los">{{ los }}</option>
          </select>
        </div>
        <div class="filter-group">
          <label class="filter-label">Job Code</label>
          <select class="filter-select" [(ngModel)]="filters.jobCode">
            <option *ngFor="let job of jobCodes" [value]="job">{{ job }}</option>
          </select>
        </div>
        <div class="filter-group">
          <label class="filter-label">Excused Status</label>
          <select class="filter-select" [(ngModel)]="filters.excusedStatus">
            <option value="">All</option>
            <option value="Yes">Yes</option>
            <option value="No">No</option>
            <option value="Pending">Pending (Empty)</option>
          </select>
        </div>
        <div class="filter-group">
          <label class="filter-label">Date Range</label>
          <div class="date-picker-wrapper">
            <div class="date-picker-display" [class.active]="showDatePicker" (click)="toggleDatePicker()">
              <span>{{ getDateLabel() }}</span>
              <span>▼</span>
            </div>
            <div class="date-picker-dropdown" [class.show]="showDatePicker">
              <div class="date-option" [class.selected]="filters.dateRange === 'yesterday'" (click)="selectDateOption('yesterday')">
                <span class="date-option-label">Yesterday</span>
              </div>
              <div class="date-option" (click)="selectDateOption('2days')">
                <span class="date-option-label">2 Days Ago</span>
              </div>
              <div class="date-option" (click)="selectDateOption('3days')">
                <span class="date-option-label">3 Days Ago</span>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="filter-actions">
        <button class="btn btn-primary" (click)="applyFilters()">
          <span>✓</span>
          <span>Apply Filters</span>
        </button>
        <button class="btn btn-secondary" (click)="resetFilters()">
          <span>↻</span>
          <span>Reset</span>
        </button>
        <button class="btn btn-secondary" (click)="refreshGrid()">
          <span>🔄</span>
          <span>Refresh</span>
        </button>
      </div>
    </div>

    <!-- Stats Cards -->
    <div class="stats-section">
      <div class="stat-card">
        <div class="stat-icon pending">⏳</div>
        <div class="stat-content">
          <h3>{{ stats.pending }}</h3>
          <p>Pending Review</p>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon excused">✓</div>
        <div class="stat-content">
          <h3>{{ stats.excused }}</h3>
          <p>Excused</p>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon unexcused">✗</div>
        <div class="stat-content">
          <h3>{{ stats.unexcused }}</h3>
          <p>Unexcused</p>
        </div>
      </div>
    </div>

    <!-- Validation Banner -->
    <div class="validation-banner" *ngIf="showValidationBanner">
      <h4>
        <span>⚠️</span>
        <span>Please correct the following errors:</span>
      </h4>
      <ul class="validation-list">
        <li *ngFor="let error of validationErrors">{{ error }}</li>
      </ul>
    </div>

    <!-- Data Table -->
    <div class="table-section">
      <div class="table-header">
        <div class="table-title">Late Arrival Records</div>
        <div class="table-actions">
          <button class="btn btn-sm btn-secondary" (click)="selectAll()" [disabled]="!currentPersona.canEdit">
            <span>☑️</span>
            <span>Select All</span>
          </button>
          <button class="btn btn-sm btn-secondary" (click)="openBulkExcusedModal()" [disabled]="selectedRows.size === 0 || !currentPersona.canEdit">
            <span>📝</span>
            <span>Bulk Excused</span>
          </button>
          <button class="btn btn-sm btn-secondary" (click)="openBulkCommentModal()" [disabled]="selectedRows.size === 0 || !currentPersona.canEdit">
            <span>💬</span>
            <span>Bulk Comment</span>
          </button>
          <button class="btn btn-sm btn-success" (click)="approveSelected()" [disabled]="selectedRows.size === 0 || !currentPersona.canEdit">
            <span>✓</span>
            <span>Approve Selected</span>
          </button>
        </div>
      </div>

      <div class="table-container">
        <table class="data-table">
          <thead>
            <tr>
              <th class="checkbox-col">
                <input type="checkbox" 
                       [checked]="selectedRows.size === records.length && records.length > 0"
                       (change)="toggleSelectAll()">
              </th>
              <th (click)="sortTable('employeeId')" class="sortable">
                Employee ID <span>{{ getSortIcon('employeeId') }}</span>
              </th>
              <th (click)="sortTable('scheduleIn')" class="sortable">
                Schedule In <span>{{ getSortIcon('scheduleIn') }}</span>
              </th>
              <th (click)="sortTable('scheduleOut')" class="sortable">
                Schedule Out <span>{{ getSortIcon('scheduleOut') }}</span>
              </th>
              <th (click)="sortTable('clockedIn')" class="sortable">
                Clocked In <span>{{ getSortIcon('clockedIn') }}</span>
              </th>
              <th (click)="sortTable('clockedOut')" class="sortable">
                Clocked Out <span>{{ getSortIcon('clockedOut') }}</span>
              </th>
              <th (click)="sortTable('excused')" class="sortable">
                Excused (Y/N) <span class="required">*</span> <span>{{ getSortIcon('excused') }}</span>
              </th>
              <th>Comment</th>
              <th>Kronos Status</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let record of records" [class.selected]="selectedRows.has(record.id)">
              <td class="text-center">
                <input type="checkbox"
                       [checked]="selectedRows.has(record.id)"
                       [disabled]="!currentPersona.canEdit"
                       (change)="toggleRowSelection(record.id)">
              </td>
              <td><span class="employee-id">{{ record.employeeId }}</span></td>
              <td><span class="time-value">{{ record.scheduleIn }}</span></td>
              <td><span class="time-value">{{ record.scheduleOut }}</span></td>
              <td><span class="time-value">{{ record.clockedIn }}</span></td>
              <td><span class="time-value">{{ record.clockedOut }}</span></td>
              <td>
                <select class="excused-select" 
                        [ngClass]="[getExcusedClass(record.excused), hasError(record.id, 'excused') ? 'validation-error' : '']"
                        [disabled]="!currentPersona.canEditExcused"
                        [(ngModel)]="record.excused"
                        (change)="updateField(record.id, 'excused', record.excused)">
                  <option value="">— Select —</option>
                  <option value="Yes">Yes</option>
                  <option value="No">No</option>
                </select>
              </td>
              <td>
                <textarea class="comment-textarea"
                          [ngClass]="hasError(record.id, 'comment') ? 'validation-error' : ''"
                          [disabled]="!currentPersona.canEditComment"
                          maxlength="500"
                          [(ngModel)]="record.comment"
                          (input)="updateField(record.id, 'comment', record.comment)"
                          placeholder="Enter comment (max 500 chars)..."></textarea>
                <div class="char-count" [ngClass]="getCharCountClass(record.comment)">
                  {{ getCharCount(record.comment) }}
                </div>

                <!-- AMH Section -->
                <div class="amh-section" *ngIf="currentPersona.showAMH">
                  <div class="amh-header">
                    <div class="amh-title">
                      <span>🔐</span>
                      <span>AMH Authorization</span>
                    </div>
                    <div class="amh-badge" [class.complete]="record.amhReason && record.amhAttachment">
                      {{ (record.amhReason && record.amhAttachment) ? '✓ Complete' : '⚠ Required' }}
                    </div>
                  </div>

                  <div class="amh-field">
                    <div class="amh-field-label">
                      <span class="amh-field-label-text">SM's Original Comment</span>
                      <span class="optional-tag">Reference</span>
                    </div>
                    <div class="amh-context">
                      <div class="amh-context-label">Site Manager wrote:</div>
                      <div class="amh-context-text">{{ record.comment || 'No comment provided' }}</div>
                    </div>
                  </div>

                  <div class="amh-field">
                    <div class="amh-field-label">
                      <span class="amh-field-label-text">Authorization Reason<span class="required-star">*</span></span>
                    </div>
                    <textarea class="amh-textarea"
                              [ngClass]="hasError(record.id, 'amhReason') ? 'validation-error' : ''"
                              [(ngModel)]="record.amhReason"
                              (input)="updateField(record.id, 'amhReason', record.amhReason)"
                              placeholder="Why are you acting on behalf? (e.g., 'Covering for SM - On leave')"></textarea>
                    <div class="amh-hint">Provide clear justification - this is audited for compliance</div>
                  </div>

                  <div class="amh-field">
                    <div class="amh-field-label">
                      <span class="amh-field-label-text">Supporting Document<span class="required-star">*</span></span>
                    </div>
                    <div class="amh-upload-area" 
                         [ngClass]="[record.amhAttachment ? 'has-file' : '', hasError(record.id, 'amhAttachment') ? 'validation-error' : '']"
                         (click)="fileInput.click()">
                      <div class="amh-upload-icon">{{ record.amhAttachment ? '✓' : '📎' }}</div>
                      <div class="amh-upload-text">{{ record.amhAttachment ? 'File Uploaded' : 'Click to Upload' }}</div>
                      <div class="amh-upload-hint">{{ record.amhAttachment || 'PDF, DOC, DOCX, JPG, PNG (Max 10MB)' }}</div>
                    </div>
                    <input #fileInput type="file" style="display: none;"
                           accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"
                           (change)="handleFileUpload($event, record.id)">
                    <div class="amh-file-display" *ngIf="record.amhAttachment" [class.show]="record.amhAttachment">
                      <span class="amh-file-name">📄 {{ record.amhAttachment }}</span>
                      <button class="amh-remove-btn" (click)="removeFile(record.id); $event.stopPropagation()">Remove</button>
                    </div>
                    <div class="amh-hint">🔒 Files encrypted and retained 90+ days for compliance</div>
                  </div>

                  <div class="amh-field">
                    <div class="amh-field-label">
                      <span class="amh-field-label-text">Additional Notes</span>
                      <span class="optional-tag">Optional</span>
                    </div>
                    <textarea class="amh-textarea"
                              style="min-height: 60px;"
                              [(ngModel)]="record.amhNotes"
                              (input)="updateField(record.id, 'amhNotes', record.amhNotes)"
                              placeholder="Any additional context or information..."></textarea>
                  </div>
                </div>
              </td>
              <td>
                <span class="kronos-badge" [ngClass]="'kronos-' + record.kronosStatus">
                  {{ getKronosIcon(record.kronosStatus) }} {{ getKronosText(record.kronosStatus) }}
                </span>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Pagination -->
      <div class="pagination-section">
        <div class="pagination-info">
          <div>
            <strong>{{ pagination.totalRecords }}</strong> records, 
            page <strong>{{ pagination.currentPage }}</strong> of <strong>{{ pagination.totalPages }}</strong>
          </div>
          <div class="rows-per-page">
            <label>Rows per page:</label>
            <select (change)="changeRowsPerPage($event)" [value]="pagination.rowsPerPage">
              <option value="25">25</option>
              <option value="50">50</option>
              <option value="100">100</option>
            </select>
          </div>
        </div>
        <div class="pagination-controls">
          <button class="page-btn" (click)="goToPage(1)" [disabled]="pagination.currentPage === 1">
            <span>⟪</span>
            <span>First</span>
          </button>
          <button class="page-btn" (click)="goToPage(pagination.currentPage - 1)" [disabled]="pagination.currentPage === 1">
            <span>‹</span>
            <span>Previous</span>
          </button>
          <div class="page-numbers">
            <button *ngFor="let page of getPageNumbers()" 
                    class="page-number"
                    [class.active]="page === pagination.currentPage"
                    (click)="goToPage(page)">
              {{ page }}
            </button>
          </div>
          <button class="page-btn" (click)="goToPage(pagination.currentPage + 1)" [disabled]="pagination.currentPage === pagination.totalPages">
            <span>Next</span>
            <span>›</span>
          </button>
          <button class="page-btn" (click)="goToPage(pagination.totalPages)" [disabled]="pagination.currentPage === pagination.totalPages">
            <span>Last</span>
            <span>⟫</span>
          </button>
        </div>
      </div>
    </div>
  </div>
</div>

<!-- Bulk Excused Modal -->
<div class="modal-overlay" *ngIf="showBulkExcusedModal" (click)="closeBulkExcusedModal()">
  <div class="modal-content" (click)="$event.stopPropagation()">
    <div class="modal-header">
      <h3>Bulk Update Excused Status</h3>
      <button class="modal-close" (click)="closeBulkExcusedModal()">✕</button>
    </div>
    <div class="modal-body">
      <p>Apply Excused status to <strong>{{ selectedRows.size }}</strong> selected record(s):</p>
      <div class="bulk-field">
        <label class="bulk-label">Excused Status:</label>
        <select class="bulk-select" [(ngModel)]="bulkExcusedValue">
          <option value="">— Select —</option>
          <option value="Yes">Yes</option>
          <option value="No">No</option>
        </select>
      </div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-secondary" (click)="closeBulkExcusedModal()">Cancel</button>
      <button class="btn btn-primary" (click)="applyBulkExcused()">Apply to Selected</button>
    </div>
  </div>
</div>

<!-- Bulk Comment Modal -->
<div class="modal-overlay" *ngIf="showBulkCommentModal" (click)="closeBulkCommentModal()">
  <div class="modal-content" (click)="$event.stopPropagation()">
    <div class="modal-header">
      <h3>Bulk Update Comment</h3>
      <button class="modal-close" (click)="closeBulkCommentModal()">✕</button>
    </div>
    <div class="modal-body">
      <p>Apply comment to <strong>{{ selectedRows.size }}</strong> selected record(s):</p>
      <div class="bulk-field">
        <label class="bulk-label">Comment:</label>
        <textarea class="bulk-textarea" 
                  [(ngModel)]="bulkCommentValue"
                  maxlength="500" 
                  placeholder="Enter comment (max 500 chars)..."></textarea>
        <div class="char-count" [ngClass]="getBulkCharCountClass()">
          {{ getBulkCharCount() }}
        </div>
      </div>
      <div class="bulk-note">
        <strong>Note:</strong> This comment will be applied to all selected records. Per-row success/failure summary will be shown after submission.
      </div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-secondary" (click)="closeBulkCommentModal()">Cancel</button>
      <button class="btn btn-primary" (click)="applyBulkComment()">Apply to Selected</button>
    </div>
  </div>
</div>

<!-- Loading Overlay -->
<div class="loading-overlay" *ngIf="showLoading">
  <div class="loading-spinner"></div>
</div>

<!-- Toast Notification -->
<div class="toast" [class.show]="showToast" [ngClass]="toastType">
  <span class="toast-icon">{{ toastType === 'success' ? '✓' : toastType === 'error' ? '✗' : 'ℹ️' }}</span>
  <span class="toast-message">{{ toastMessage }}</span>
</div>
